-- ============================================================================
-- v1310: Seed / sample data — Core Banking registers (FIN pack)
-- ============================================================================
-- Owner request 2026-10-21: demo records for the five Core Banking registers, 10 each (50 total):
-- Product Configuration, Parameterisation, Interfaces, Environments, Customisation.
-- Continues the v1306 scenario (fictional "Northbridge Bank" core banking replacement). No
-- vendor/product/brand names (rule 26). Environment addresses use private (10.x) ranges and
-- contain no credentials.
--
-- Scope: project SEED334-PRJ-08 (resolved by project_code) and its account; nothing is inserted
-- if it does not exist. display_id = '' so the Admin ID Generation trigger assigns LREG-…
-- (rule 16.2). field_values match the v1307-v1309 definitions: multi_line = newline-joined
-- string (also valid before v1309 turns two Interfaces fields into lists), multi_select = JSON
-- array of option keys, dropdown = option key, number/currency = JSON number, dates YYYY-MM-DD.
-- Fixed hex-only UUIDs (…-4000-a0RR-…) + ON CONFLICT (id) DO NOTHING — idempotent.
-- Prerequisites: v947, v1307, v1308.
-- ============================================================================

WITH proj AS (
  SELECT id, account_id FROM public.projects WHERE project_code = 'SEED334-PRJ-08' LIMIT 1
)
INSERT INTO public.local_register_records
  (id, register_id, display_id, title, description, status, field_values, account_id, project_id, record_project_id)
SELECT v.id::uuid, v.register_id::uuid, '', v.title, v.description, v.status, v.field_values::jsonb,
