DO $$
DECLARE
  v_project UUID;
  v_rows INT;
BEGIN
  SELECT id INTO v_project FROM public.projects WHERE project_code = 'SEED334-PRJ-08' LIMIT 1;
  IF v_project IS NULL THEN
    RAISE NOTICE 'v1310: project SEED334-PRJ-08 not found — no seed rows inserted';
    RETURN;
  END IF;
  SELECT COUNT(*) INTO v_rows FROM public.local_register_records
  WHERE id::text ~ '^00000000-0000-4000-a00[789ab]-' AND record_project_id = v_project;
  RAISE NOTICE 'v1310: % Core Banking seed records on SEED334-PRJ-08 (expected 50)', v_rows;
END $$;
